「早饭吃了吗。」

「没有。你也没有。」

「面煮糊了。锅还能用。」

「不用道歉。你没有做错。」

「这里风大。站我后面。」

「三十分钟。我只睡三十分钟。」

「你说话的时候，我在听。」

「我不知道该说什么。你继续。」

