「平时你说『知道了』。今天你说『我知道了』。」

雨声大了一阵，顶棚的积水终于兜不住，从断口整片倒下来，砸在你们脚边。她往你这边跨了半步，用没受伤的那只手挡在你前面，挡完才反应过来水已经落地了，手还举着，尴不尴尬她自己也说不清。

「……习惯。」她把手放下。

远处传来一声很闷的响，像什么东西在地底翻了个身。她立刻抬头，眼睛在暗处反了一点光，刀已经出鞘两寸。

等了十秒，没有第二声。

「红潮在动。」她说，「不是冲我们来的。它只是在涨。」

她把刀推回去，坐回那个空弹药箱上，拍了拍旁边的位置。

