她站起来，去拿器械盘。站起来的时候右手在身侧垂了一下，没有立刻抬起来。你看见了。她也知道你看见了。

「手给我看看。」你说。

「我没事。」

「丽芙。」

她停了两秒，把右手伸出来。手指在抖，抖得不明显，但一直没停。

