「训练弄的。」

「训练不会弄成这样。」她拿棉签沾了碘，动作很轻，「边缘是齐的，是刀。你挡了一下。」

「……嗯。」

「下次别用手挡。」她说，「用手挡，手就没了。」

她处理伤口的时候不说话。包完，她把你的手翻过来看了看，确认绷带没有压到关节，才放开。

「三天别碰水。」她说，「我知道你记不住，所以我每天来一次。」

她从口袋里摸出一颗糖，放在你手边。

「拿着。不是药。」

糖是软糖，橘子味的。你抬头看她，她已经转过身去收拾器械了。

她收拾器械盘，背对着你，忽然开口。

