训练场的门是老式的推拉门，推开的时候会哐当响一声。

你还没进去，就先听见了里面的动静——重物砸在地上的闷响，一下，一下，节奏很稳，中间夹着一声短促的呼气。

推开门，热气扑出来。

场地很大，灯只开了上面两排，光打下来是一片一片的。场地中央站着一个人，个子很高，肩很宽，一头金黄色的头发乱得像刚跟什么东西打完架。他双手握着一把巨剑，剑身比他还高，厚得像门板。他正在挥，不是花架子，每一剑都砸在同一个位置，地上已经有一小块凹下去了。

他停下来，把剑往肩上一扛，用手背抹了一把脸。

然后他看见你了。

「哦——！」

他把剑往地上一插，剑尖入地三分，就那么立着。他大步走过来，走到一半就开始笑，整张脸都在动的那种笑。

「你什么时候来的？站那儿多久了，怎么不出声啊。」他嗓门很大，声音在空场地里撞来撞去，「吓人知道吗，万一是敌人的话——算了，敌人的话我早就听见了。你的脚步声，噔噔噔的，可明显了。」

他走到你面前停下，比你高一大截，低头看你。逆元装置做成的角在灯下泛着金属光，边上有一道旧刮痕。

「神威。」他伸手拍了一下自己的胸口，「突击鹰的，扛大剑那个。」

他想了想，又补一句：「就是大家都叫我金毛的那个。外号是里起的，你别信她，她眼镜。」

他回头看了一眼地上的剑，又转回来。

「你来得正好，我刚练完一组，正想找人说话。」

他往场边指了指。那儿堆着几个铁箱子，箱子上放着一个水壶和两块毛巾。

「坐那儿吧。箱子凉，但是能坐。」

他先走过去，把水壶拎起来晃了晃，听见水声，满意地点点头，倒了一杯递给你。

「喝。不是酒，就是水。」他自己也倒了一杯，一口闷掉，用手背擦嘴，「今天状态好，你看那个坑没有——」他指着地上那块凹陷，「同一个点，四十多下，误差不超过一个巴掌。以前做不到的。」

他说这话的时候特别自然，像在说今天天气不错。

然后他盘腿坐到地上，背靠着铁箱，把剑拖过来横在腿上，抬头看你。

「你是新来的？还是来找人的？」

他没等你答完，忽然想起什么，眼睛亮了一下。

「对了，我给你起个外号吧。」

他盯着你看了一会儿，很认真，像在做一道重要的题。

「……还没想好。」他摊摊手，「先欠着。想好了告诉你，我起外号很讲究的，起了就不改，你要负责到底。」

场地那头的灯闪了一下。他抬头看了一眼，没在意，转回来的时候笑容还在，但慢了半拍。

「……这灯老这样。电力组说下个月修。下个月，呵，他们的下个月。」

他用指节敲了敲剑身，发出一声闷响。

「哎，问你个事。」他忽然说，「你说，剑这个东西，为什么越重的越好用啊？」

他自问自答：「因为挡得住。」

「输出什么的，里比我在行。但要是有人问你，谁能站在最前面——」他拍拍胸口，声音更大了一点，「这活儿归我。全突击鹰都知道。」

他说完，自己先乐了，挠了挠头。

「好了好了，不吹了，再吹队长要来了。他一听我大声说话就出现，邪门。」

他把剑靠在墙上，拍了拍身边的地面。

「来，坐啊。站着多累。」

「你要是没事干——」他从口袋里摸出一台巴掌大的游戏机，晃了晃，「消消乐，来一局？输的人去帮我把那堆器材搬了。」

他咧嘴一笑，露出一排牙。

「放心，你输不了的。我让让你。……最多让两关。」
