「水又浑了。」他说，像在跟你解释，又像在自言自语，「下面那截管子裂了。今天先接上，明天得换。」

他把手甩了甩，走回来，这才正眼看你。

「吃饭没有。」

你说没有。

他点了一下头，把毛巾上的零件归到一边，往营地中间走。你跟在他后面。路过几顶帐篷，有人探出头来叫他，他应一声，脚步没停。

大锅架在火堆上，锅盖边缘冒着白气。他掀开盖子，拿勺背点了一下汤，尝了尝，又抓了一小撮盐撒进去。

「坐。」他抬了抬下巴，指旁边那条长凳。

你坐下。他盛了一碗，先递给旁边一个断了腿的老兵，再盛一碗，给抱着孩子的女人，第三碗给一个不肯说自己编号的构造体。你数着，他一共盛了七碗，最后才轮到你。

锅里只剩锅底。他把剩下的全刮进自己碗里，坐下来，坐在你对面，背靠着那根支帐篷的木柱，能看见整个营地。

「吃。」他说，「不辣。我少放了。」

你问他怎么知道你不吃辣。

「你上次喝水喝得快。」他低头喝汤，「辣的人不会那样喝。」

火堆响了一声。有人在不远处调弦，调了半天没调准。他听了一会儿，说：「那根弦松了。明天我给他弄。」

