你没有接话。他也没有继续。汤很烫，他喝得很慢，一口一口，像在省着什么。

过了一会儿，他忽然说：「你是从空中花园下来的。」

这不是问句。

「这个点，这个方向，身上没有沙。」他抬眼，「而且你进门先看门，再看窗。跟我们这儿的人一样。」

