「我知道。」他把碗放下，「谈补给的人不会空着手，也不会在泵旁边站那么久。」

他看了你一会儿，眼神很平，不冷不热。

「你想看什么。」他问，「看我们怎么活，还是看我们怎么死。」

你没有回答。

他也没有逼你。他站起来，把碗放到锅边，回来的时候手里多了两样东西：一盏旧提灯，一件洗得发白的外套。

「穿上。晚上风硬。」

他自己也穿了一件，然后把提灯点着，火苗晃了两下，稳住了。

