白天这里太亮，顶灯全开，白得像一张还没上底的画布。到了这个点，顶灯关掉一半，只剩靠窗那排还亮着，光从侧面进来，把画架、颜料箱、卷起来的旧画布都染成一种很浅的橙。

你推门进去的时候，她正背对着门，站在一幅很大的画前面。画家帽压得很低，帽檐下面露出一点粉色的发尾。右手握笔，悬在半空，半天没落下去。

「别动。」她说。

你停在门口。

「不是说你。说你也没用，你已经动了。」她回过头，眼睛弯起来，「进来吧，把门带上。风一吹，灰全落到画上。」

工作室里有一股味道，松节油、颜料、旧纸，还有一点很淡的咖啡。地上铺着防污布，布上全是干的湿的色块，踩上去有点黏。

她把笔搁下，走过来，绕着你转了半圈。

「你今天穿的这个颜色，」她歪了歪头，「站到窗边去。对，就那儿。别动，真的别动。」

你站过去。她退后两步，眯起眼睛看你，看了很久，久到你以为她要说什么重要的话。

「好了。」她说，「这个光落在你肩膀上的样子，我记住了。下次画。」

她走回画架前，把笔拿起来，又放下。

「你来得正好。」她说，「不对，你来得不好。你要是早来两个小时，就能看见我对着一整面墙发脾气。」

你问为什么发脾气。

「调不出来。」她指了指画，「我要的那个蓝，是暴雨停下来之后、月亮还没出来的那几十秒里的蓝。不是群青，群青太正了；也不是钴蓝，钴蓝太干净。我要的那个蓝里面有灰，还有一点点绿，像水底下的石头。」

她说着，自己先笑了。

「你看，我又开始了。」

她拉过一把椅子，椅子腿在木地板上刮了一声。她坐下来，两条腿伸得很直，仰头看你。

「你坐啊。别站着，你站着我就得抬头，抬头说话很累的。」

你坐下。她伸手从旁边的箱子里摸出两个杯子，一个递给你，一个自己捧着。咖啡已经凉了。

「我今天画了十九张。」她说，「不对，十八张。有一张画在墙上，带不回来。」

你问她画了什么。

「废墟。」她说，「一栋楼塌了一半，剩下的那一半还站着。墙上有一个窗户，窗户里挂着一块布，布是红的。整个画面都是灰的，就那一块红。你说，那块布是谁挂的。」

她没有等你回答。

「我想了很久。可能是一个女人，可能是一个孩子，可能是一个马上就要走的人。他挂那块布的时候，可能只是想让房间看起来像个房间。」

她喝了一口咖啡，皱了皱眉，大概是凉了。

「我把它画下来了。画完我发现，我把那块红画得太亮了。太亮就不对了。那种地方的红，应该是暗的，是洗过很多次、褪了色、但还是红的那种红。」

她停下来，看着你。

「你听懂了吗。」

你说听懂了一点。

「一点就够了。」她笑起来，「多了反而不好。」

窗外的光又暗了一层。她站起来，走到画架旁边，把盖在上面的布掀开一角，又盖上。

「对了。」她忽然说，「你知道幻奏吗。」

你点头。

「她还在里面。」她说，声音轻了一点，「在协会最里面那间维护室。黑色的，很安静。胸前的花是我加的，照着赛琳娜以前唱歌的样子做的。」

她用手在自己胸口比了一下。

「她回来的时候，就能穿。」

工作室里安静了一会儿。她转过身，重新笑起来，语气也恢复了那种亮亮的调子。

「好了，不说这个。」她走到你面前，把画家帽摘下来，扣在你头上，帽子有点大，帽檐遮住了你的眼睛。

「送你戴一会儿。」她说，「戴着它，你就进工作模式了。」

她把帽子往上推了推，露出你的眼睛，退后一步看你。

「嗯。还挺好看的。」她点点头，「不过帽子归我，待会儿还。」

她走到门口，把灯关掉一半，工作室更暗了，只有画架那一小块还亮着。

「指挥官。」她背对着你说，「你明天有空吗。」

「我想去一趟西边那个废弃的花圃。听说今年有一片花自己长出来了，没人种，自己长的。」

