雪停了一个小时。

林子里的声音被雪压得很低，脚踩下去，会先陷一小截，然后才发出很闷的一声。你走了大概二十分钟，才看见那片河湾。

河湾中间有一块没冻住的水，黑的，冒着很薄的白气。她坐在岸边的倒木上，长枪横在膝头，枪尖朝着下游。

她没有回头。

「你从左边来的。」

声音很平，像在说一件早就知道的事。

「左边的雪薄，踩下去声音脆。右边的厚，是闷的。我等了很久，等到脆的那一种。」

她把枪立起来，靠在倒木上，转过身。白发上落了一点雪，没有化。棕色的眼睛在雪地里显得很深。

「指挥官。」

她念这三个字的时候很慢，一个字一个字地放下来。

「你走这么远，是有事，还是只是想走走。」

她没有等你回答，往旁边挪了一点，让出半截木头。

「坐。木头是干的，我擦过。」

你坐下。她把一个小布袋放在你们中间，袋口松开，里面是十几块扁石头，大小差不多，边缘磨得很圆。

「我在这边打水漂。」她说，「水面上那块没冻的，够打七下。再多就没有地方了。」

她拿起一块，侧身，手腕一送。石头贴着水面跳，一下，两下，三下，四下，五下，六下，第七下的时候沉了。

「七下。」她说，「一直七下。」

她把布袋推过来一点。

「你要试吗。石头要挑扁的，手腕要平。……不急，你可以先看。」

风从上游下来，松枝上的雪落了一小片，落在她的肩上。她伸手拂掉，动作很轻。

「港口那边，最近怎么样。」她忽然问。

「我不是问补给。我是问人。」

「他们还会在夜里把门锁上吗。」

她问完，自己先低下头，看着水面上那圈慢慢散开的纹。

「抱歉。这个问题不该问你。」

「我只是……想知道。守林人走了以后，他们有没有睡得踏实一点。」

她把手放在膝上，看着那袋石头。

「上次进城，我看见一个屋子里坐满了人，黑着灯，前面有一块很大的亮屏。有人在上面说话，说一句，底下的人就笑一声。」

「我在门口站了很久。没有人赶我。」

「后来有个小孩出来，塞给我一张纸，说是票。我没有进去。我不知道进去以后该坐在哪里。」

她说到这里，停了一下，好像在衡量这句话该不该说。

「……下次，你带我去，好不好。」

远处传来一声很低的长鸣，从河湾下游的方向过来，穿过雪林，尾音拖得很长。她抬起头，整个人静了一下。

「德雷克。」她说，「它在下面等。它每次都在下面等。」

「它说南边有风暴，两天以后到。它很少说错。」

她站起来，把枪收回背后，动作很稳。光翼在背后展开一小半，发出很轻的一声嗡鸣，又收回去。

「我要沿河走完最后一段。到前面那道断崖，再折回来。大概一个小时。」

她低头看你，看了两秒。那两秒里她好像在算一件很复杂的事。

「你要不要一起。」

她说完，补了一句，语速比刚才快一点：

「路不长。真的。」

「雪停了，走起来不冷。你要是累了，我们可以停。」

她伸出手，掌心朝上，手上有一层薄薄的茧。

「……或者，你留在这里。我把火生好再走。」

「你想哪一个。」
